"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["64394"],{50664(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.composicao_origem_nao_selecionada","status":422,"titulo":"A origem da composi\xe7\xe3o RETIRADA_DE_OUTRA_MODALIDADE n\xe3o est\xe1 selecionada nesta oferta"},"descricao":{"codigo":"uniplus.selecao.configuracao_distribuicao_vagas.composicao_origem_nao_selecionada","requisitos":[],"oQueAconteceu":["Uma modalidade com `composicaoVagas: RETIRADA_DE_OUTRA_MODALIDADE` declara um\\n`composicaoOrigemCodigo` que existe no cadastro de modalidades, mas **n\xe3o\\nest\xe1 entre as modalidades selecionadas nesta mesma oferta**. A valida\xe7\xe3o de\\n[`modalidade_selecionada.composicao_origem_obrigatoria`](/erros/uniplus.selecao.modalidade_selecionada.composicao_origem_obrigatoria)\\ns\xf3 prova que o campo foi preenchido \u2014 esta confer\xeancia, separada, prova que ele\\naponta para algo que de fato existe **nesta** distribui\xe7\xe3o. Uma modalidade\\nn\xe3o pode retirar vagas de outra que a oferta nem ofereceu.","Esta confer\xeancia roda depois que todas as modalidades da distribui\xe7\xe3o j\xe1 foram\\ncriadas individualmente (todas passaram pelas confer\xeancias de forma, incluindo\\n`composicao_origem_obrigatoria`), sobre o conjunto delas \u2014 por isso \xe9 uma\\ncausa de `ConfiguracaoDistribuicaoVagas`, n\xe3o de `ModalidadeSelecionada`.\\nVerifica s\xf3 a primeira modalidade do conjunto cuja refer\xeancia falhar, e s\xf3 a\\nprimeira refer\xeancia dessa modalidade (origem, antes de destino/par/fallback\\n\u2014 ver\\n[`remanejamento_destino_nao_selecionado`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.remanejamento_destino_nao_selecionado)).\\nAcumula, no mesmo array `errors[]`, com\\n[`configuracao_distribuicao_vagas.modalidade_duplicada`](/erros/uniplus.selecao.configuracao_distribuicao_vagas.modalidade_duplicada)\\n\u2014 a confer\xeancia irm\xe3 do mesmo bloco \u2014, sob o campo\\n`distribuicaoVagas[<\xedndice>].modalidadeIds`."],"comoResolver":["Inclua a modalidade de origem em `modalidadeIds`, na mesma distribui\xe7\xe3o, ou\\ncorrija, no cadastro de modalidades de Configura\xe7\xe3o, o c\xf3digo de origem\\ndeclarado para apontar a uma modalidade que de fato est\xe1 sendo selecionada\\nnesta oferta."],"ondeAparece":["Defini\xe7\xe3o de distribui\xe7\xe3o de vagas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Configuracao distribuicao vagas"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);